{
  "is_valid": <true/false>,
  "is_all_clos_mapped": <true/false>,
  "is_all_sessions_mapped": <true/false>,
  "unmapped_clos": [
    { "clo_id": "...", "clo_code": "...", "suggestion": "..." }
  ],
  "unmapped_sessions": [
    { "session_id": "...", "chapter_title": "...", "suggestion": "Should be mapped to CLO... because the topic covers..." }
  ],
  "data": [
    { "session_id": "...", "clo_id": "...", "confidence_score": <evaluation score from 0.0 to 1.0>, "reasoning": "<evaluation statement of Topic and teaching methods alignment>" }
